from pathlib import Path
from copy import deepcopy
import re
import hashlib
from docx import Document
from docx.text.paragraph import Paragraph
from docx.oxml import OxmlElement
from docx.shared import Pt

ROOT = Path(__file__).resolve().parents[2]
source = ROOT / 'Robustness_Certification_RIS_Networks_Conference_V4.docx'
target = ROOT / 'Robustness_Certification_RIS_Networks_Conference_V5.docx'
source_hash = hashlib.sha256(source.read_bytes()).hexdigest()
doc = Document(source)
ps = list(doc.paragraphs)
assert len(ps) == 70


def change(i, text):
    p = ps[i]
    props = deepcopy(p.runs[0]._r.rPr) if p.runs and p.runs[0]._r.rPr is not None else None
    p.clear()
    run = p.add_run(text)
    if props is not None:
        run._r.insert(0, props)
    return p


def after(p, text, equation=False):
    elem = OxmlElement('w:p')
    if p._p.pPr is not None:
        elem.append(deepcopy(p._p.pPr))
    p._p.addnext(elem)
    new = Paragraph(elem, p._parent)
    new.style = doc.styles['Normal']
    new.paragraph_format.keep_with_next = False
    new.paragraph_format.widow_control = True
    run = new.add_run(text)
    if equation:
        run.font.size = Pt(9.5)
    return new


change(2, 'This paper studies configuration-specific robustness certification for discrete reconfigurable intelligent surface (RIS)-assisted multi-cell wireless networks under bounded channel uncertainty. Conventional robust RIS optimization establishes feasibility inside a prescribed uncertainty set, but does not directly quantify the robustness boundary of an obtained configuration. We define a configuration-specific robustness certificate as the largest dimensionless relative uncertainty factor preserving robust QoS for a fixed beamforming/RIS configuration. Its nested feasible sets motivate a statewise S-procedure feasibility test and bisection. The certificate supports a robustness-constrained wireless energy-efficiency (WEE) selection rule; Pareto filtering preserves the optimal objective value over the candidate pool. A certified reuse horizon follows conditionally from an explicit relative channel-drift bound. The evaluation protocol combines certificate validation, a single-channel WEE–robustness landscape, and paired multi-channel selection comparisons with fixed and normalized requirements. Numerical oracle outputs are distinguished from exact certificates because feasibility tolerances can admit small QoS violations. The framework is a certification and selection layer, without introducing another full discrete RIS optimization procedure.')
change(7, 'The contributions are: (1) a configuration-specific robustness certificate, expressed as a relative uncertainty scaling factor, and its monotone robustness profile; (2) a dominance-filtering result showing that the robustness-constrained max-WEE objective admits a nondominated optimum in a finite candidate pool; and (3) a stability-aware configuration-selection rule with a paired evaluation protocol across independent channel realizations. Certified reuse time is a conditional interpretation under an explicit bound on total relative channel deviation. Exact theoretical guarantees are separated from tolerance-dependent numerical feasibility decisions.')

change(11, 'For each user (l,k), let h_lk=[h_0,lkᵀ,…,h_(L−1),lkᵀ]ᵀ ∈ ℂ^(LM) stack the BS-to-user channel blocks. Define v_ij ∈ ℂ^(LM) by placing w_ij ∈ ℂ^M in BS block i and zeros in all other blocks. This notation represents per-BS transmission without assuming joint transmission of each user’s data. For a fixed configuration X=(W,Θ), the SINR is')
change(12, 'γ_lk(X,h_lk) = |h_lkᴴ v_lk|² /\n    (Σ_(i,j)≠(l,k) |h_lkᴴ v_ij|² + σ²).   (2)')
change(13, 'The nominal aggregate equivalent channel ĥ_lk(X) depends on the RIS configuration. Its uncertainty model is')
change(14, 'h_lk = ĥ_lk(X) + Δh_lk,    ||Δh_lk||₂ ≤ r_lk(X,ε),\nr_lk(X,ε) = ε max(||ĥ_lk(X)||₂, r_min).   (3)')
change(16, 'γ_lk(X, ĥ_lk(X)+Δh_lk) ≥ γ̄_lk,\n    for all ||Δh_lk||₂ ≤ r_lk(X,ε).   (4)')
change(19, 'Here γ_lk(X) is evaluated at the nominal equivalent channel, and P_tot includes transmit, circuit, and RIS hardware/controller power. WEE is the unweighted nominal sum spectral efficiency divided by total power, reported in bit/s/Hz/W. Bandwidth is not multiplied into the numerator, and user weights are not used. The numerical specialization uses the same QoS target γ̄_lk=2 for every user.')
change(21, 'max_{W,Θ} WEE(W,Θ)\ns.t. γ_lk(W,Θ,ĥ_lk(X)+Δh_lk) ≥ γ̄_lk,\n     ∀l,k, ∀Δh_lk: ||Δh_lk||₂ ≤ r_lk(X,ε),\n     W∈𝒲, Θ∈𝒬_B^N.   (6)')
change(22, 'The present paper treats X as fixed during certification. Candidates may come from a robust design stage or another feasible configuration-generation method. In the numerical protocol, B=2 is fixed. Within each channel realization, all policies share one nominal channel drop and one candidate pool. The existing generator uses discrete phase mixtures with alignment fraction/jitter, centralized ZF directions that also suppress inter-cell leakage, worst-case fixed-point power control at several design uncertainty factors ε_d and SINR margins, and feasible power slack/perturbation. The per-candidate ε_d is distinct from the common selection requirement ε_min. In particular, not every candidate is designed for ε_d=0.05. Certification does not re-optimize X.')
change(24, 'With the zero-padded beamformers above, define\nA_lk(X)=v_lk v_lkᴴ − γ̄_lk Σ_(i,j)≠(l,k) v_ij v_ijᴴ.\nThis Hermitian LM-by-LM matrix has the same BS-block structure as the implementation. For fixed X, each robust QoS constraint becomes')
change(27, 'Δh_lkᴴ Δh_lk − r_lk(X,ε)² ≤ 0.   (8)')
change(28, 'For ε>0, the ball has a strictly feasible interior because r_min>0. Under this regularity condition, the S-procedure gives equivalence to the existence of λ_lk≥0 satisfying the following LMI. At ε=0, feasibility is checked directly using the nominal SINR; the positive-radius regularity argument is not invoked for the singleton uncertainty set.')
change(29, 'M_lk(X,ε,λ_lk) =\n[ A_lk+λ_lk I,                    A_lk ĥ_lk\n  ĥ_lkᴴ A_lk,  ĥ_lkᴴ A_lk ĥ_lk−γ̄_lk σ²−λ_lk r_lk(X,ε)² ] ⪰ 0.   (9)')
change(35, 'ε_cert(X) is the largest dimensionless relative uncertainty factor preserving robust QoS for fixed X. The uncertainty balls are nested, so F_X is non-increasing. With continuous channel/SINR expressions and positive receiver noise, feasibility is preserved at a finite limiting feasible factor; thus the boundary is included. This theoretical property concerns exact feasibility. The numerical implementation uses an approximate feasibility oracle, whose output must be distinguished from the exact certificate.')
change(36, 'With an exact oracle and a valid bracket satisfying F_X(ε_low)=1 and F_X(ε_high)=0, bisection evaluates\nε_mid=(ε_low+ε_high)/2.   (12)\nIf feasible, update ε_low; otherwise update ε_high. Stop when\nε_high−ε_low ≤ δ_ε.   (13)\nUnder these assumptions, ε_low is a lower bound on ε_cert with bracket error at most δ_ε. If the search cap remains feasible, only a lower-bound-censored result is available. No beamforming or RIS re-optimization occurs during certification.')
p = after(ps[36], 'Numerical implementation. Let F̃_X denote the tolerance-dependent oracle and ε̃_cert its reported bisection output. The implementation accepts a normalized LMI minimum eigenvalue down to −τ, with τ=2×10⁻⁴ in the current configuration; its bisection tolerance is δ_ε=10⁻⁴. These tolerances play different roles. A lower endpoint accepted by F̃_X need not be a lower bound on the exact ε_cert. The code field epsilon_cert stores this numerical output; the distinction ε̃_cert is used here to avoid changing the theoretical definition while stating the implementation’s actual guarantee.')
p = after(p, 'The statuses EXACT_BRACKET, LOWER_BOUND_CENSORED, and NOMINAL_INFEASIBLE describe the numerical oracle’s bracket or nominal decision. EXACT_BRACKET does not mean exact arithmetic or independently verified robust feasibility. Boundary checks that reuse the same oracle establish internal consistency. A strict robustness claim additionally requires independent residual/feasibility validation and control of oracle error; Monte Carlo may reveal a counterexample but cannot establish universal feasibility. The current fragile-configuration discrepancy is reported in Section 9.')

change(38, 'For fixed X, let ĥ_lk(X,0) be the nominal equivalent channel used for certification and h_lk(X,t) the actual equivalent channel at time t. Assume, for every user and throughout the reuse interval,\n||h_lk(X,t)−ĥ_lk(X,0)||₂\n    / max(||ĥ_lk(X,0)||₂,r_min) ≤ ρ(t).   (14)\nHere ρ is a common nonnegative, nondecreasing bound on total relative deviation, including any initial CSI error. A fixed configuration is guaranteed to satisfy robust QoS whenever ρ(t)≤ε_cert(X). Consequently, define')
change(39, 'T_cert(X)=sup{t≥0 : ρ(t)≤ε_cert(X)}.   (15)\nThe requirement at any particular time is the displayed inequality; a supremum endpoint need not be included if ρ has a jump. For ρ(t)=νt with ν>0 and zero initial deviation,\nT_cert(X)=ε_cert(X)/ν.   (16)\nIf an initial error bound ε₀ and additional drift bound νt are both present, use ρ(t)=ε₀+νt. For ε₀≤ε_cert, the horizon becomes (ε_cert−ε₀)/ν; if ε₀>ε_cert, even initial reuse is not certified. T_cert is conditional on this deterministic deviation bound, not a prediction of actual QoS failure time. Substituting ε̃_cert gives only a numerical derived horizon unless the underlying certificate has been independently validated.')

change(41, 'Let 𝒳 be the finite candidate pool. The WEE-only reference is\nX_WEE ∈ arg max_{X∈𝒳} WEE(X).   (17)\nA configuration with lower WEE may have a larger robustness certificate. Configuration X_i dominates X_j when WEE(X_i)≥WEE(X_j) and ε_cert(X_i)≥ε_cert(X_j), with at least one strict inequality. The nondominated configurations form the candidate-pool Pareto frontier.')
after(ps[42], 'Pareto preservation. If a dominated configuration is feasible for (18), its dominator also satisfies the robustness threshold and has no smaller WEE. Repeating this argument in a finite pool reaches a nondominated configuration. Hence, whenever (18) is feasible, at least one nondominated optimum exists and Pareto filtering preserves the optimal WEE value. Dominated configurations can still tie in WEE; the claim is preservation of objective value, not identical selected IDs under all tie rules.')
change(44, 'The implementation applies Pareto filtering, then the robustness threshold, and selects maximum WEE among the eligible candidates. An empty eligible set is reported as infeasible, with no selected configuration and no fallback or threshold reduction. The robustness-only reference X_R∈arg max ε_cert(X) represents the robustness extreme and is auxiliary to the WEE-only comparison. All policies use the same pool. Selection changes arise from the certificate-aware constraint; Pareto filtering does not improve the constrained optimum. In numerical experiments, the policies operate on ε̃_cert, so their physical robustness interpretation remains subject to Section 4.')
after(ps[44], 'Selection properties. At ε_min=0 the proposed optimal WEE equals the WEE-only optimum. As ε_min increases, the feasible sets shrink, so optimal feasible WEE cannot increase. These properties allow ties and unchanged selections. The empirical question is the frequency and magnitude of configuration changes, the WEE retained, and the robustness gained across channel realizations; monotonicity alone is not evidence of a performance advantage.')
change(48, 'Candidate generation is decoupled from certification; selection uses only candidate-level WEE and robustness values. The layer can therefore evaluate pools produced by different feasible generators without requiring another search over the discrete RIS space. This modularity is an architectural property; the present experiments use one fixed ZF-based generator and do not empirically establish equal performance across different optimizers.')
after(ps[56], 'These expressions describe certification after a valid bracket is obtained; bracket-expansion checks and the initial nominal check add oracle calls. For the straightforward pairwise Pareto implementation, filtering costs O(J²), followed by O(J) work per selection threshold. For S channel realizations, the certification term scales to O(S J I_bis C_LMI), excluding candidate generation. Oracle timings include all users and the numerical multiplier searches.')

change(58, 'The study has three main experiments. Exp3 contains a single-channel illustration and a multi-channel paired validation, rather than a fourth experiment. All runs use the same system and candidate-generation parameters, including L=2, K=3, M=12, N=32, B=2 and γ̄=2. WEE is nominal and unweighted. Numerical robustness values below refer to ε̃_cert, stored as epsilon_cert in the output files. Strict physical certification is not inferred from an unvalidated numerical bracket.')
change(59, 'Experiment 1 — Certificate consistency and independent validation. Representatives include maximum-WEE, maximum-reported-certificate, and fragile low-certificate configurations. Deterministic checks at αε̃_cert, with α∈{0.90,0.95,0.99,1.00,1.01,1.05,1.10}, test the bisection/oracle boundary internally. Independent Monte Carlo samples inside relative balls over 0–3ε̃_cert test empirical QoS, without estimating or defining ε_cert. Validation must report both violation frequency and actual SINR residuals, and separately examine fragile cases using an independent feasibility calculation; reuse of the original oracle is not an independent proof.')
after(ps[59], 'Current numerical limitation. In the stored Exp1 run, candidate 26 has ε̃_cert≈0.000952148. At α=0.125, the recorded violation rate is 99%, although the numerical oracle regards the radius as feasible. The recorded minimum SINR is approximately 1.998827 against a target of 2. The violation magnitude is small, but it occurs within the reported certificate and therefore prevents interpreting that value as a strict robust guarantee. By contrast, the first sampled violations for the higher-certificate representatives occur at α=2.0 and 1.875. These observations must be reported separately; the fragile result cannot be explained away as normal behavior of an exact certificate. Independent numerical validation remains necessary before a strict certification claim is made.')
change(60, 'Experiment 2 — WEE–robustness landscape and Pareto analysis. A target pool of 40 unique configurations is built on the illustrative nominal channel (seed 20260706) and evaluated in the (WEE, ε̃_cert) plane. B=2 is fixed. The WEE-only and robustness-only choices, nondominated set, and ε_design=0.05 reference line are shown. The frontier characterizes this generated pool, not the globally attainable design space; no candidates, values, or seeds are altered to force a trade-off.')
change(61, 'Experiment 3 — Stability-aware selection. The single-channel illustration compares WEE-only, robustness-only, and the robustness-constrained max-WEE rule on one pool. The requirement is swept over αε̃_max with α∈{0,0.25,0.50,0.75,0.90,0.95} and ε̃_max=max_X ε̃_cert(X). WEE, reported robustness, conditional reuse horizon, and eligibility counts are recorded. The fixed ε_min=ε_design=0.05 comparison is reported separately from the normalized sweep. The multi-channel extension below uses the same policy definitions and generation protocol.')
change(62, 'The existing single-channel reference run accepted 40 configurations in 125 attempts. Its WEE range is [0.6319,1.2792] bit/s/Hz/W and its reported ε̃_cert range is approximately [0.00095,0.11396], with two nondominated configurations and 10 values below 0.05. Candidate 34 is WEE-optimal (WEE=1.2792, ε̃_cert=0.09089); candidate 6 maximizes reported robustness (WEE=1.2460, ε̃_cert=0.11396). Fixed ε_min=0.05 leaves candidate 34 selected, whereas α=0.90 selects candidate 6. These are descriptive observations for this seed and numerical protocol, not evidence of universal performance or independently established exact certificate boundaries.')
p = after(ps[62], 'Multi-channel protocol. The formal configuration specifies 20 independent channel realizations with consecutive seeds 60001–60020, fixed before observing results. Only the channel seed changes; hardware, CSI uncertainty model, B=2, pool target 40, and candidate-generation hyperparameters are unchanged. For each realization, a pool is generated once and its WEE and reported certificate evaluated once, then shared by all policies and thresholds. Cache provenance binds channel seed, configuration signature and configuration fingerprint. Actual pool size, attempts, accepted count, unique phase/configuration counts and rejection reasons are retained. A nonempty short pool is used with a warning; empty pools and exceptional failures remain in the requested-seed accounting, with no replacement seed.')
p = after(p, 'Fixed requirement. Set ε_min=0.05 for every realization. Record full-pool eligible count, selected configuration, and whether the proposed selection is feasible. If no candidate reaches the requirement, return no selection. The feasibility rate is calculated over valid realizations; failed realizations are listed separately, and the feasible fraction of all requested realizations is also reported. Selection-change rate uses feasible valid pairs and compares complete configuration signatures with the WEE-only selection.')
p = after(p, 'Normalized sensitivity. For each realization, use the predetermined fractions α∈{0,0.25,0.50,0.75,0.90,0.95} of that pool’s ε̃_max. This sweep measures response to relative requirement strength; it does not impose the same absolute uncertainty requirement across channels. Record WEE retention WEE_sel/WEE_WEE, absolute robustness gain ε̃_sel−ε̃_WEE, selected ε̃_sel/ε̃_max and selection-change rate. A zero denominator yields a missing ratio. If certificates are censored, normalization is explicitly based on the reported lower-bound values, not a known exact maximum.')
p = after(p, 'Paired aggregation. Compute within-realization differences ΔWEE=WEE_sel−WEE_WEE and Δε̃=ε̃_sel−ε̃_WEE before aggregating across seeds. Absolute Δε̃ is primary; percentage changes are reported only when the reference denominator exceeds 10⁻⁸ in magnitude. Summaries give valid counts and mean, median and population standard deviation for WEE and reported robustness; T̃_cert=ε̃_cert/ν with ν=0.002 s⁻¹ is auxiliary and conditional. Missing, infeasible and failed observations are distinguished rather than imputed as zeros. Sanity checks enforce the unconstrained WEE upper bound, threshold satisfaction, maximum robustness for the auxiliary baseline, zero-threshold WEE equivalence, and non-increasing selected WEE over the sweep.')
p = after(p, 'Independent sampling and presentation. An optional 100-sample complex-ball check at ε=0.05 uses RNG seed 90000+channel_seed, independent of pool generation, with common error directions across policies within each realization. It records hold/violation counts, hold rate and minimum SINR-minus-target margin. Any sampled violation inside a reported certificate is retained and flagged. Figure A uses separate WEE and robustness panels with paired observations; Figure B shows median WEE retention and selected robustness normalized by ε̃_max, with 25%–75% quantile bands. All observations remain in the data; no outlier or unfavorable seed is removed.')
p = after(p, 'Execution status. The formal 20-realization protocol has been implemented, but a completed 20-seed result is not available for this draft. The two-seed smoke test (60001 and 60002) checks execution and output integrity only and is not used to claim multi-channel generalization. Formal aggregate findings and any resulting performance–robustness conclusion must be written from the complete saved run after the numerical certificate limitation has been addressed. Fixed-threshold results must be retained even if selection changes are rare; the preset normalized sweep must not be retuned after observing outcomes.')

change(64, 'The certificate adds a configuration-level robustness axis to nominal WEE. A finite candidate map can identify nondominated alternatives and quantify the cost of a specified robustness requirement. WEE and robustness need not be negatively correlated across the whole pool: the relevant question is whether a binding requirement excludes the WEE-optimal configuration and which alternatives remain. Pareto filtering preserves the constrained optimum; it does not itself create a performance gain. The observed frontier is conditional on the channel and generator and is not a dense approximation to the global feasible frontier.')
change(65, 'The interpretation is model-dependent. ε_cert is defined relative to the adopted uncertainty set and QoS constraints; T_cert also requires a valid bound on total channel deviation. Numerical results require an additional distinction: accepting slightly negative normalized LMI margins can overstate a strict certificate, particularly for nearly active nominal QoS constraints. The observed fragile-configuration discrepancy is an unresolved numerical validation issue, not evidence that the exact guarantee permits interior violations. Reducing the bisection interval alone does not remove oracle error. Likewise, empirical zero-violation samples cannot certify an entire ball.')
change(68, 'This paper formulates a configuration-specific robustness certificate for discrete RIS-assisted multi-cell networks and a robustness-constrained WEE selection rule over a fixed candidate pool. With exact robust-feasibility decisions, nested uncertainty sets permit bisection, and Pareto filtering preserves the constrained optimum. A reuse horizon follows only under an explicit total relative channel-deviation bound. The implemented evaluation separates single-channel illustration, fixed-requirement multi-channel comparison, and normalized requirement sensitivity. The current tolerance-dependent oracle requires further independent validation for fragile configurations; completed multi-channel evidence is also needed before making a general empirical trade-off claim. The framework’s intended role remains certification and configuration management after candidate generation, without asserting global optimality of the underlying RIS design problem.')
change(69, 'Key notation: X=(W,Θ) is a fixed configuration; v_ij is its zero-padded aggregate beamformer; F_X and ε_cert denote exact robust feasibility and its relative uncertainty boundary; F̃_X and ε̃_cert denote numerical oracle outputs (code field epsilon_cert); ε_d is a per-candidate design factor; ε_min is the selection requirement; ε_design=0.05 is the fixed comparison requirement; α is the normalized requirement fraction; T_cert is a conditional exact reuse horizon; ν=0.002 s⁻¹ is the adopted relative drift-rate bound.')

# Short margin notes identify substantive revisions without changing the manuscript flow.
doc.add_comment(ps[36].runs, 'V5 revision: the conservative lower-bound statement is conditional on an exact feasible/infeasible bracket. The new following paragraphs distinguish numerical oracle output and document the remaining validation issue.', author='V5 revision', initials='V5')
doc.add_comment(ps[38].runs, 'V5 revision: total actual-channel deviation is measured from the certification reference, for every user and fixed configuration. Initial CSI error is included explicitly.', author='V5 revision', initials='V5')
doc.add_comment(ps[41].runs, 'V5 revision: restored equation (17). Pareto preservation permits ties and does not imply a separate performance improvement.', author='V5 revision', initials='V5')
doc.add_comment(ps[61].runs, 'V5 revision: fixed and normalized requirements are separated. The multi-channel protocol and execution-status paragraphs below do not claim completed 20-seed results.', author='V5 revision', initials='V5')

for p in doc.paragraphs:
    if p.style.name.startswith('Heading'):
        p.paragraph_format.keep_with_next = True
    p.paragraph_format.widow_control = True

doc.core_properties.title = 'Configuration-Specific Robustness Certification for Stability-Aware Selection of Discrete RIS Configurations'
doc.core_properties.subject = 'V5: revised theory, numerical qualification, and paired multi-channel protocol'
doc.core_properties.version = '5'
doc.save(target)

# Structural verification of the delivered package and its key scientific qualifiers.
check = Document(target)
text = '\n'.join(p.text for p in check.paragraphs)
for term in ['(17)', '60001–60020', '99%', 'Execution status.', 'no fallback', 'ε̃_cert', 'ρ(t)=ε₀+νt']:
    assert term in text, term
assert all(text.count(f'({n})') >= 1 for n in range(1, 24))
assert len([p for p in check.paragraphs if p.style.name == 'Heading 1']) == len([p for p in ps if p.style.name == 'Heading 1'])
assert len(check.comments) == 4
assert hashlib.sha256(source.read_bytes()).hexdigest() == source_hash
assert check.sections[0].page_width == doc.sections[0].page_width
(ROOT/'tmp/docx_v5/v5_extracted.txt').write_text(text,encoding='utf-8')
print(f'Saved {target.name}; {len(check.paragraphs)} paragraphs; 4 revision comments; source unchanged.')
